import polars as pl

def dataframes_equal(df1: pl.DataFrame, df2: pl.DataFrame) -> bool:
    """
    Check if two polars DataFrames are exactly equal (same schema and values).

    Args:
        df1: First DataFrame
        df2: Second DataFrame

    Returns:
        True if DataFrames are identical, False otherwise
    """
    return df1.frame_equal(df2)


# Example usage
if __name__ == "__main__":
    df1 = pl.DataFrame({
        "a": [1, 2, 3],
        "b": ["x", "y", "z"]
    })

    df2 = pl.DataFrame({
        "a": [1, 2, 3],
        "b": ["x", "y", "z"]
    })

    df3 = pl.DataFrame({
        "a": [1, 2, 4],
        "b": ["x", "y", "z"]
    })

    df4 = pl.DataFrame({
        "a": [1, 2, 3],
        "b": ["x", "y", "z"],
        "c": [4, 5, 6]
    })

    print(dataframes_equal(df1, df2))  # True
    print(dataframes_equal(df1, df3))  # False (different values)
    print(dataframes_equal(df1, df4))  # False (different schema)

